pat_wk=re.compile(r'\[(\d\d:\d\d:\d\d\.\d+)\].*sched_wak(?:eup|ing):.*comm = "([^"]+)", tid = (\d+)')

def parse_ts(s):
    h,m,rest=s.split(':'); sec=float(rest); return int(h)*3600+int(m)*60+sec

def sample(window0, window1):
    wakes=[]
    for ev in ['sched_waking','sched_wakeup']:
        wakes += get_lines(event=ev, t0=secs(window0), t1=secs(window1), limit=800)
    sws = get_lines(event='sched_switch', t0=secs(window0), t1=secs(window1), limit=800)
    lastwake={}
    delays=[]
    for ln in sorted(wakes+sws, key=lambda x: x[1:16]):
        m=pat_wk.search(ln)
        if m:
            ts,comm,tid=m.groups(); lastwake[tid]=(parse_ts(ts),comm); continue
        m=pat_sw.search(ln)
        if m:
            ts,comm,tid=m.groups();
            if tid in lastwake:
                d=(parse_ts(ts)-lastwake[tid][0])*1000
                delays.append((comm,tid,d))
                del lastwake[tid]
    return delays
